import { useState, useEffect, useMemo } from "react";
import { useQuery, navigate } from "sibilla";

const C = { primary: "#0066CC", dark: "#004080", darker: "#003366", text: "#17324D", muted: "#5C6F82", light: "#F2F7FC", border: "#D9E1E8" };
const FONT = "'Titillium Web', Geneva, Tahoma, sans-serif";
const PALETTE = ["#0066CC", "#008758", "#CC7A00", "#D9364F", "#7A3EC4", "#00838F", "#5C6F82", "#B5560B"];

const INT = {
  vault: "Esplora un vault Markdown (collezione vault, id dalla rotta): intestazione con nome, descrizione e percorso; albero delle cartelle (campo cartella delle note) ed elenco delle note del vault con titolo, cartella, tag (separati da virgola) e modificata_il, ricerca per titolo e filtro per cartella e tag; clic su una nota apre /note/:id. Stile Bootstrap Italia come la home: header slim #003366, header e menu blu #0066CC, font Titillium Web, card bianche con ombra, footer #004080.",
  nota: "Lettura di una nota (collezione note, id dalla rotta): contenuto Markdown renderizzato (titoli, elenchi, checklist, grassetto/corsivo, codice, citazioni), [[wikilink]] cliccabili che aprono la nota con quel titolo (/note/:id), tag come chip, metadati (vault, cartella, modificata_il), sezione backlink con le note che la citano, pulsanti per segnare/togliere preferita, modificare titolo/contenuto/tag/cartella ed eliminare la nota. Stile Bootstrap Italia come la home (header blu #0066CC, Titillium Web, footer #004080).",
  grafo: "Grafo dei collegamenti tra le note",
  importa: "Importa un vault Obsidian dal computer: selezione di una cartella locale (input file con webkitdirectory) o di più file .md, anteprima dei file trovati, nome e descrizione del vault; crea un record nella collezione vault (percorso = nome cartella) e una nota per ogni file .md (titolo dal nome file, cartella dal percorso relativo, tag dal frontmatter YAML e dai #tag nel testo salvati separati da virgola, contenuto Markdown, modificata_il dalla data del file) con barra di avanzamento; permette anche di creare un vault vuoto. Stile Bootstrap Italia come la home (header blu #0066CC, Titillium Web, footer #004080)."
};
const go = {
  home: () => navigate("/", {}, "Home del Vault Markdown"),
  nota: (id) => navigate("/note/:id", { id }, INT.nota),
  vault: (id) => navigate("/vault/:id", { id }, INT.vault),
  grafo: () => navigate("/grafo", {}, INT.grafo),
  importa: () => navigate("/importa", {}, INT.importa)
};

const Q = (table, select, orderBy, limit = null) => ({ table, select, join: [], where: [], groupBy: [], aggregates: [], orderBy, limit });
const qVault = Q("vault", ["id", "nome"], [{ field: "nome", dir: "asc" }]);
const qNote = Q("note", ["id", "titolo", "vault_id", "cartella", "tag", "contenuto", "preferita", "modificata_il"], [{ field: "modificata_il", dir: "desc" }], 1000);

const norm = (s) => String(s || "").trim().toLowerCase();
const tagsOf = (s) => String(s || "").split(",").map((t) => t.trim().replace(/^#/, "")).filter(Boolean);
const fmtDate = (d) => { if (!d) return "—"; const x = new Date(String(d).slice(0, 10) + "T00:00:00"); return isNaN(x) ? String(d) : x.toLocaleDateString("it-IT", { day: "numeric", month: "long", year: "numeric" }); };
const excerpt = (s) => String(s || "").replace(/^---[\s\S]*?---/, "").replace(/\[\[([^\]|]+)(\|([^\]]+))?\]\]/g, (m, a, b, c) => c || a).replace(/[#>*_`\-\[\]]/g, " ").replace(/\s+/g, " ").trim().slice(0, 160);
const PAGE = 12;

export default function TutteLeNote() {
  const v = useQuery(qVault);
  const n = useQuery(qNote);
  const [q, setQ] = useState("");
  const [vf, setVf] = useState("");
  const [cf, setCf] = useState("");
  const [tf, setTf] = useState("");
  const [pref, setPref] = useState(false);
  const [sort, setSort] = useState("desc");
  const [shown, setShown] = useState(PAGE);

  useEffect(() => {
    if (document.getElementById("bi-font")) return;
    const l = document.createElement("link");
    l.id = "bi-font"; l.rel = "stylesheet";
    l.href = "https://fonts.googleapis.com/css2?family=Titillium+Web:wght@400;600;700&display=swap";
    document.head.appendChild(l);
  }, []);
  useEffect(() => setShown(PAGE), [q, vf, cf, tf, pref, sort]);

  const vaults = v.rows || [];
  const notes = n.rows || [];
  const color = (id) => { const i = vaults.findIndex((x) => String(x.id) === String(id)); return PALETTE[(i < 0 ? vaults.length : i) % PALETTE.length]; };
  const vaultName = (id) => vaults.find((x) => String(x.id) === String(id))?.nome || "Senza vault";

  const inVault = useMemo(() => notes.filter((x) => !vf || String(x.vault_id) === vf), [notes, vf]);
  const cartelle = useMemo(() => [...new Set(inVault.map((x) => x.cartella).filter(Boolean))].sort((a, b) => a.localeCompare(b)), [inVault]);
  const tags = useMemo(() => [...new Set(inVault.flatMap((x) => tagsOf(x.tag)))].sort((a, b) => a.localeCompare(b)), [inVault]);

  const list = useMemo(() => {
    const f = norm(q);
    const r = inVault.filter((x) => (!f || norm(x.titolo).includes(f)) && (!cf || x.cartella === cf) && (!tf || tagsOf(x.tag).map(norm).includes(norm(tf))) && (!pref || x.preferita));
    return r.sort((a, b) => {
      if (sort === "titolo") return String(a.titolo).localeCompare(String(b.titolo));
      const da = String(a.modificata_il || ""), db = String(b.modificata_il || "");
      return sort === "desc" ? db.localeCompare(da) : da.localeCompare(db);
    });
  }, [inVault, q, cf, tf, pref, sort]);

  const reset = () => { setQ(""); setVf(""); setCf(""); setTf(""); setPref(false); };
  const active = q || vf || cf || tf || pref;
  const loading = v.loading || n.loading, error = v.error || n.error;
  const nav = [["Home", go.home], ["Tutte le note", () => {}, true], ["Grafo dei collegamenti", go.grafo], ["Importa vault", go.importa]];
  const sel = { height: 44, border: `1px solid ${C.border}`, borderRadius: 4, padding: "0 12px", fontFamily: FONT, fontSize: 16, color: C.text, background: "#fff", width: "100%" };
  const lab = { fontSize: 14, fontWeight: 600, display: "flex", flexDirection: "column", gap: 4 };

  return (
    <div style={{ fontFamily: FONT, color: C.text, background: "#fff", fontSize: 18 }}>
      <div style={{ background: C.darker, color: "#fff" }}>
        <div className="max-w-6xl mx-auto px-6 flex items-center justify-between" style={{ height: 48, fontSize: 15 }}>
          <span style={{ fontWeight: 600 }}>Sibilla · Archivio digitale</span>
          <button onClick={go.grafo} style={{ color: "#fff", fontWeight: 600 }}>← Torna al grafo</button>
        </div>
      </div>
      <header style={{ background: C.primary, color: "#fff" }}>
        <div className="max-w-6xl mx-auto px-6 py-6">
          <button onClick={go.home} style={{ color: "#fff", textAlign: "left" }}>
            <div style={{ fontSize: 32, fontWeight: 700, lineHeight: 1.1 }}>Vault Markdown</div>
            <div style={{ fontSize: 16, opacity: 0.9 }}>Leggi e consulta le tue note in stile Obsidian</div>
          </button>
        </div>
        <nav aria-label="Menu principale" style={{ borderTop: "1px solid rgba(255,255,255,.18)" }}>
          <div className="max-w-6xl mx-auto px-6 flex flex-wrap">
            {nav.map(([label, fn, act]) => <button key={label} onClick={fn} style={{ color: "#fff", fontWeight: 600, fontSize: 16, padding: "14px 18px", borderBottom: act ? "3px solid #fff" : "3px solid transparent" }}>{label}</button>)}
          </div>
        </nav>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-8">
        <div style={{ fontSize: 14, color: C.muted }}><button onClick={go.home} style={{ color: C.primary, textDecoration: "underline" }}>Home</button> / Tutte le note</div>
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <h1 style={{ fontSize: 40, fontWeight: 700, margin: "6px 0 10px", lineHeight: 1.15 }}>Tutte le note</h1>
            <p style={{ fontSize: 20, color: C.muted, maxWidth: 760, margin: "0 0 24px" }}>Cerca tra le note di tutti i vault, filtra per vault, cartella o tag e aprile per leggerle.</p>
          </div>
          <button onClick={go.importa} style={{ background: C.primary, color: "#fff", fontWeight: 700, fontSize: 16, padding: "10px 20px", borderRadius: 4, marginBottom: 24 }}>Importa vault</button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 mb-4" style={{ background: C.light, padding: 16, borderRadius: 4 }}>
          <label style={{ ...lab, gridColumn: "span 1" }} className="lg:col-span-2">Cerca per titolo
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Es. Riunione, progetto…" style={sel} type="search" />
          </label>
          <label style={lab}>Vault
            <select value={vf} onChange={(e) => { setVf(e.target.value); setCf(""); setTf(""); }} style={sel}>
              <option value="">Tutti i vault</option>
              {vaults.map((x) => <option key={x.id} value={String(x.id)}>{x.nome}</option>)}
            </select>
          </label>
          <label style={lab}>Cartella
            <select value={cf} onChange={(e) => setCf(e.target.value)} style={sel}>
              <option value="">Tutte le cartelle</option>
              {cartelle.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </label>
          <label style={lab}>Tag
            <select value={tf} onChange={(e) => setTf(e.target.value)} style={sel}>
              <option value="">Tutti i tag</option>
              {tags.map((t) => <option key={t} value={t}>#{t}</option>)}
            </select>
          </label>
        </div>

        <div className="flex flex-wrap items-center justify-between gap-4 mb-5">
          <div className="flex flex-wrap items-center gap-5" style={{ fontSize: 16 }}>
            <span><strong>{list.length}</strong> {list.length === 1 ? "nota trovata" : "note trovate"}</span>
            <label className="flex items-center gap-2"><input type="checkbox" checked={pref} onChange={(e) => setPref(e.target.checked)} style={{ width: 18, height: 18, accentColor: C.primary }} />Solo preferite</label>
            {active && <button onClick={reset} style={{ color: C.primary, fontWeight: 600, textDecoration: "underline" }}>Azzera filtri</button>}
          </div>
          <label className="flex items-center gap-2" style={{ fontSize: 15, fontWeight: 600 }}>Ordina per
            <select value={sort} onChange={(e) => setSort(e.target.value)} style={{ ...sel, width: 230 }}>
              <option value="desc">Modifica più recente</option>
              <option value="asc">Modifica meno recente</option>
              <option value="titolo">Titolo (A–Z)</option>
            </select>
          </label>
        </div>

        {error ? (
          <div role="alert" style={{ borderLeft: "4px solid #D9364F", background: "#FDF2F4", padding: 16, borderRadius: 4 }}>Impossibile caricare le note: {String(error.message || error)}</div>
        ) : loading ? (
          <p style={{ color: C.muted }}>Caricamento delle note…</p>
        ) : list.length === 0 ? (
          <div style={{ background: C.light, padding: 32, borderRadius: 4, textAlign: "center", color: C.muted }}>
            {notes.length === 0 ? <>Non ci sono ancora note. <button onClick={go.importa} style={{ color: C.primary, fontWeight: 600, textDecoration: "underline" }}>Importa un vault</button></> : <>Nessuna nota corrisponde ai filtri. <button onClick={reset} style={{ color: C.primary, fontWeight: 600, textDecoration: "underline" }}>Azzera filtri</button></>}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {list.slice(0, shown).map((x) => (
                <article key={x.id} onClick={() => go.nota(x.id)} className="cursor-pointer flex flex-col" style={{ background: "#fff", borderRadius: 4, boxShadow: "0 2px 20px rgba(0,0,0,.08)", padding: 20, borderTop: `4px solid ${color(x.vault_id)}` }}>
                  <div className="flex items-center justify-between gap-2" style={{ fontSize: 13, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".05em", color: C.muted }}>
                    <button onClick={(e) => { e.stopPropagation(); go.vault(x.vault_id); }} style={{ color: color(x.vault_id), fontWeight: 700, textTransform: "uppercase" }}>{vaultName(x.vault_id)}</button>
                    {x.preferita ? <span title="Preferita" style={{ color: "#CC7A00", fontSize: 18 }}>★</span> : null}
                  </div>
                  <h2 style={{ fontSize: 22, fontWeight: 700, margin: "8px 0 4px", color: C.primary, lineHeight: 1.2 }}>{x.titolo}</h2>
                  {x.cartella && <div style={{ fontSize: 14, color: C.muted }}>📁 {x.cartella}</div>}
                  <p style={{ fontSize: 16, color: C.text, margin: "10px 0", flex: 1 }}>{excerpt(x.contenuto) || <em style={{ color: C.muted }}>Nota vuota</em>}</p>
                  {tagsOf(x.tag).length > 0 && (
                    <div className="flex flex-wrap gap-2 mb-3">
                      {tagsOf(x.tag).slice(0, 5).map((t) => <button key={t} onClick={(e) => { e.stopPropagation(); setTf(t); }} style={{ fontSize: 13, fontWeight: 600, color: C.dark, background: C.light, border: `1px solid ${C.border}`, borderRadius: 12, padding: "2px 10px" }}>#{t}</button>)}
                    </div>
                  )}
                  <div className="flex items-center justify-between" style={{ fontSize: 14, color: C.muted, borderTop: `1px solid ${C.border}`, paddingTop: 10 }}>
                    <span>Modificata il {fmtDate(x.modificata_il)}</span>
                    <span style={{ color: C.primary, fontWeight: 700 }}>Leggi →</span>
                  </div>
                </article>
              ))}
            </div>
            {shown < list.length && (
              <div className="flex justify-center mt-8">
                <button onClick={() => setShown((s) => s + PAGE)} style={{ border: `2px solid ${C.primary}`, color: C.primary, fontWeight: 700, fontSize: 16, padding: "10px 24px", borderRadius: 4 }}>Mostra altre ({list.length - shown})</button>
              </div>
            )}
          </>
        )}
      </main>

      <footer style={{ background: C.dark, color: "#fff" }}>
        <div className="max-w-6xl mx-auto px-6 py-8 flex flex-wrap items-end justify-between gap-6">
          <div>
            <div style={{ fontSize: 24, fontWeight: 700 }}>Vault Markdown</div>
            <div style={{ fontSize: 15, opacity: 0.85, marginTop: 6 }}>Interfaccia ispirata a Bootstrap Italia, il design system dei siti della Pubblica Amministrazione.</div>
          </div>
          <div className="flex flex-wrap gap-5" style={{ fontSize: 15, fontWeight: 600 }}>
            {[nav[0], nav[2], nav[3]].map(([label, fn]) => <button key={label} onClick={fn} style={{ color: "#fff", textDecoration: "underline" }}>{label}</button>)}
          </div>
        </div>
      </footer>
    </div>
  );
}

import { useState, useEffect, useMemo } from "react";
import { useQuery, updateRecord, deleteRecord, navigate } from "sibilla";

const C = { primary: "#0066CC", dark: "#004080", darker: "#003366", text: "#17324D", muted: "#5C6F82", light: "#F2F7FC", border: "#D9E1E8", red: "#D9364F" };
const FONT = "'Titillium Web', Geneva, Tahoma, sans-serif";
const INT = {
  vault: "Esplora un vault Markdown (collezione vault, id dalla rotta): intestazione con nome, descrizione e percorso; albero delle cartelle (campo cartella delle note) ed elenco delle note del vault con titolo, cartella, tag (separati da virgola) e modificata_il, ricerca per titolo e filtro per cartella e tag; clic su una nota apre /note/:id. Stile Bootstrap Italia come la home: header slim #003366, header e menu blu #0066CC, font Titillium Web, card bianche con ombra, footer #004080.",
  nota: "Lettura di una nota (collezione note, id dalla rotta): contenuto Markdown renderizzato (titoli, elenchi, checklist, grassetto/corsivo, codice, citazioni), [[wikilink]] cliccabili che aprono la nota con quel titolo (/note/:id), tag come chip, metadati (vault, cartella, modificata_il), sezione backlink con le note che la citano, pulsanti per segnare/togliere preferita, modificare titolo/contenuto/tag/cartella ed eliminare la nota. Stile Bootstrap Italia come la home (header blu #0066CC, Titillium Web, footer #004080).",
  grafo: "Grafo dei collegamenti tra le note",
  importa: "Importa un vault Obsidian dal computer: selezione di una cartella locale (input file con webkitdirectory) o di più file .md, anteprima dei file trovati, nome e descrizione del vault; crea un record nella collezione vault (percorso = nome cartella) e una nota per ogni file .md (titolo dal nome file, cartella dal percorso relativo, tag dal frontmatter YAML e dai #tag nel testo salvati separati da virgola, contenuto Markdown, modificata_il dalla data del file) con barra di avanzamento; permette anche di creare un vault vuoto. Stile Bootstrap Italia come la home (header blu #0066CC, Titillium Web, footer #004080)."
};
const go = {
  home: () => navigate("/", {}, "Home del Vault Markdown"),
  note: () => navigate("/note", {}, "Tutte le note"),
  nota: (id) => navigate("/note/:id", { id }, INT.nota),
  vault: (id) => navigate("/vault/:id", { id }, INT.vault),
  grafo: () => navigate("/grafo", {}, INT.grafo),
  importa: () => navigate("/importa", {}, INT.importa)
};

const Q = (table, select, where = [], limit = null) => ({ table, select, join: [], where, groupBy: [], aggregates: [], orderBy: [], limit });
const qNota = Q("note", ["id", "titolo", "vault_id", "cartella", "tag", "contenuto", "preferita", "modificata_il"], [{ field: "id", op: "eq", value: "{{id}}" }], 1);
const qAll = Q("note", ["id", "titolo", "contenuto", "vault_id", "cartella", "modificata_il"], [], 1000);
const qVault = Q("vault", ["id", "nome", "percorso"]);

const norm = (s) => String(s || "").trim().toLowerCase();
const tagsOf = (s) => String(s || "").split(",").map((t) => t.trim().replace(/^#/, "")).filter(Boolean);
const slug = (s) => "h-" + norm(s).replace(/[^\p{L}\d]+/gu, "-");
const today = () => new Date().toISOString().slice(0, 10);
const fmtDate = (d) => { if (!d) return "—"; const x = new Date(String(d).slice(0, 10) + "T00:00:00"); return isNaN(x) ? String(d) : x.toLocaleDateString("it-IT", { day: "numeric", month: "long", year: "numeric" }); };
const links = (s) => [...String(s || "").matchAll(/\[\[([^\]|#]+)(?:#[^\]|]*)?(?:\|[^\]]*)?\]\]/g)].map((m) => norm(m[1]));
const routeId = () => { const m = (typeof window !== "undefined" ? window.location.pathname : "").match(/\/note\/(\d+)/); return m ? Number(m[1]) : null; };

function splitFront(src) {
  const s = String(src || "");
  const m = s.match(/^---\n([\s\S]*?)\n---\n?/);
  return m ? { offset: m[0].split("\n").length - 1, body: s.slice(m[0].length) } : { offset: 0, body: s };
}

function Inline({ text, ctx }) {
  const re = /(`[^`]+`)|(\[\[[^\]]+\]\])|(\*\*[^*]+\*\*)|(\*[^*\s][^*]*\*)|(_[^_\s][^_]*_)|(\[[^\]]+\]\([^)\s]+\))|(#[\p{L}\d_\-/]+)/gu;
  const out = []; let last = 0, m, k = 0;
  while ((m = re.exec(text))) {
    const t = m[0], i = m.index;
    if (m[7] && i > 0 && !/\s/.test(text[i - 1])) continue;
    if (i > last) out.push(text.slice(last, i));
    if (m[1]) out.push(<code key={k++} style={{ background: C.light, border: `1px solid ${C.border}`, borderRadius: 3, padding: "0 5px", fontSize: "0.9em", fontFamily: "monospace" }}>{t.slice(1, -1)}</code>);
    else if (m[2]) {
      const [raw, alias] = t.slice(2, -2).split("|");
      const target = raw.split("#")[0].trim();
      const hit = ctx.byTitle[norm(target)];
      out.push(hit
        ? <button key={k++} onClick={() => go.nota(hit.id)} style={{ color: C.primary, fontWeight: 600, textDecoration: "underline", textUnderlineOffset: 3 }}>{alias || raw}</button>
        : <span key={k++} title="Nota non trovata" style={{ color: C.muted, borderBottom: `1px dashed ${C.muted}` }}>{alias || raw}</span>);
    }
    else if (m[3]) out.push(<strong key={k++}><Inline text={t.slice(2, -2)} ctx={ctx} /></strong>);
    else if (m[4] || m[5]) out.push(<em key={k++}><Inline text={t.slice(1, -1)} ctx={ctx} /></em>);
    else if (m[6]) { const mm = t.match(/^\[([^\]]+)\]\(([^)]+)\)$/); out.push(<a key={k++} href={mm[2]} target="_blank" rel="noreferrer" style={{ color: C.primary, textDecoration: "underline" }}>{mm[1]}</a>); }
    else if (m[7]) out.push(<span key={k++} style={{ color: C.dark, background: C.light, borderRadius: 10, padding: "0 8px", fontSize: "0.85em", fontWeight: 600 }}>{t}</span>);
    last = i + t.length;
  }
  if (last < text.length) out.push(text.slice(last));
  return <>{out}</>;
}

function Markdown({ src, ctx, onToggle }) {
  const { body, offset } = splitFront(src);
  const L = body.split("\n"); const blocks = []; let i = 0, k = 0;
  const isStart = (l) => /^(#{1,6}\s|>|```|\s*([-*+]|\d+\.)\s|(-{3,}|\*{3,})\s*$)/.test(l);
  const hs = [24, 30, 25, 22, 20, 18, 18];
  while (i < L.length) {
    const l = L[i];
    if (!l.trim()) { i++; continue; }
    if (l.startsWith("```")) {
      const code = []; i++;
      while (i < L.length && !L[i].startsWith("```")) code.push(L[i++]);
      i++;
      blocks.push(<pre key={k++} style={{ background: "#1B2A3A", color: "#E6EEF6", padding: 16, borderRadius: 4, overflowX: "auto", fontSize: 14, margin: "16px 0" }}><code>{code.join("\n")}</code></pre>);
      continue;
    }
    let m = l.match(/^(#{1,6})\s+(.*)/);
    if (m) {
      const lv = m[1].length, Tag = "h" + Math.min(lv + 1, 6);
      blocks.push(<Tag key={k++} id={slug(m[2])} style={{ fontSize: hs[lv], fontWeight: 700, margin: lv <= 2 ? "28px 0 10px" : "20px 0 8px", lineHeight: 1.25, color: lv === 1 ? C.text : C.dark }}><Inline text={m[2]} ctx={ctx} /></Tag>);
      i++; continue;
    }
    if (/^(-{3,}|\*{3,})\s*$/.test(l)) { blocks.push(<hr key={k++} style={{ border: 0, borderTop: `1px solid ${C.border}`, margin: "24px 0" }} />); i++; continue; }
    if (l.startsWith(">")) {
      const q = [];
      while (i < L.length && L[i].startsWith(">")) q.push(L[i++].replace(/^>\s?/, ""));
      const call = q[0]?.match(/^\[!(\w+)\][+-]?\s*(.*)/);
      if (call) q[0] = call[2] ? `**${call[2]}**` : `**${call[1][0].toUpperCase() + call[1].slice(1)}**`;
      blocks.push(<blockquote key={k++} style={{ borderLeft: `4px solid ${C.primary}`, background: C.light, padding: "12px 18px", margin: "16px 0", color: C.text }}>{q.map((x, j) => <div key={j}><Inline text={x} ctx={ctx} /></div>)}</blockquote>);
      continue;
    }
    if (/^\s*([-*+]|\d+\.)\s/.test(l)) {
      const items = [];
      while (i < L.length && /^\s*([-*+]|\d+\.)\s/.test(L[i])) {
        const mm = L[i].match(/^(\s*)([-*+]|\d+\.)\s+(.*)/);
        items.push({ ind: Math.floor(mm[1].replace(/\t/g, "  ").length / 2), mark: mm[2], text: mm[3], line: i + offset });
        i++;
      }
      blocks.push(<ul key={k++} style={{ margin: "12px 0", padding: 0, listStyle: "none" }}>{items.map((it) => {
        const cb = it.text.match(/^\[( |x|X)\]\s*(.*)/);
        const done = cb && cb[1] !== " ";
        return (
          <li key={it.line} style={{ marginLeft: it.ind * 24, display: "flex", gap: 10, alignItems: "baseline", padding: "3px 0" }}>
            {cb ? <input type="checkbox" checked={done} onChange={() => onToggle(it.line)} style={{ width: 18, height: 18, accentColor: C.primary, transform: "translateY(3px)", cursor: "pointer" }} />
              : <span style={{ color: C.primary, fontWeight: 700, minWidth: 14 }}>{/\d/.test(it.mark) ? it.mark : "•"}</span>}
            <span style={done ? { textDecoration: "line-through", color: C.muted } : null}><Inline text={cb ? cb[2] : it.text} ctx={ctx} /></span>
          </li>);
      })}</ul>);
      continue;
    }
    const p = [];
    while (i < L.length && L[i].trim() && !(p.length && isStart(L[i]))) p.push(L[i++]);
    blocks.push(<p key={k++} style={{ margin: "12px 0" }}>{p.map((x, j) => <span key={j}>{j > 0 && <br />}<Inline text={x} ctx={ctx} /></span>)}</p>);
  }
  return <>{blocks}</>;
}

