  vault: (id) => navigate("/vault/:id", { id }, INT.vault),
  tutte: () => navigate("/note", {}, INT.tutte),
  importa: () => navigate("/importa", {}, INT.importa)
};
const Q = (table, select, orderBy, limit = null) => ({ table, select, join: [], where: [], groupBy: [], aggregates: [], orderBy, limit });
const qVault = Q("vault", ["id", "nome"], [{ field: "nome", dir: "asc" }]);
const qNote = Q("note", ["id", "titolo", "vault_id", "tag", "contenuto"], [{ field: "titolo", dir: "asc" }], 1000);

const DEF = { center: 0.05, repel: 140, linkForce: 0.5, linkDist: 70, nodeSize: 1, linkWidth: 1, textFade: 0.9 };
const norm = (s) => String(s || "").trim().toLowerCase();
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const WIKI = /\[\[([^\]|#]+)(?:#[^\]|]*)?(?:\|[^\]]*)?\]\]/g;
const rad = (d, s) => ((d.kind === "tag" ? 3 : 4) + Math.sqrt(d.deg) * 1.8) * s;

function buildGraph(notes, o) {
  const pool = notes.filter((n) => !o.vault || String(n.vault_id) === o.vault);
  const byTitle = {};
  pool.forEach((n) => { const k = norm(n.titolo); (byTitle[k] = byTitle[k] || []).push(n); });
  const nodes = new Map(), edges = new Map();
  pool.forEach((n) => nodes.set("n" + n.id, { id: "n" + n.id, ref: n.id, kind: "note", titolo: n.titolo || "Senza titolo", vault_id: n.vault_id, deg: 0 }));
  const add = (a, b) => { if (a === b) return; const k = a < b ? a + "|" + b : b + "|" + a; if (!edges.has(k)) edges.set(k, { source: a, target: b }); };
  pool.forEach((n) => {
    const txt = String(n.contenuto || ""); let m; WIKI.lastIndex = 0;
    while ((m = WIKI.exec(txt))) {
      const name = m[1].split("/").pop().trim(); const c = byTitle[norm(name)];
      if (c) { const t = c.find((x) => String(x.vault_id) === String(n.vault_id)) || c[0]; add("n" + n.id, "n" + t.id); }
      else if (o.ghosts && name) { const g = "g" + norm(name); if (!nodes.has(g)) nodes.set(g, { id: g, kind: "ghost", titolo: name, deg: 0 }); add("n" + n.id, g); }
    }
    if (o.tags) String(n.tag || "").split(",").map((s) => s.trim().replace(/^#/, "")).filter(Boolean).forEach((t) => {
      const id = "t" + norm(t); if (!nodes.has(id)) nodes.set(id, { id, kind: "tag", titolo: "#" + t, deg: 0 }); add("n" + n.id, id);
    });
  });
  const links = [...edges.values()];
  links.forEach((l) => { nodes.get(l.source).deg++; nodes.get(l.target).deg++; });
  let list = [...nodes.values()];
  const orphans = list.filter((d) => d.kind === "note" && d.deg === 0).length;
  if (!o.orphans) list = list.filter((d) => d.deg > 0);
  return { nodes: list, links, orphans, noteLinks: links.filter((l) => l.source[0] === "n" && l.target[0] === "n").length, ghosts: list.filter((d) => d.kind === "ghost").length };
}

// Simulazione fisica (repulsione, molle, gravità centrale, collisioni)
function createSim(nodes, links) {
  const byId = Object.fromEntries(nodes.map((d) => [d.id, d]));
  links.forEach((l) => { l.source = byId[l.source]; l.target = byId[l.target]; });
  nodes.forEach((d) => { d.vx = 0; d.vy = 0; });
  const s = { alpha: 1, target: 0, f: DEF };
  s.tick = () => {
    s.alpha += (s.target - s.alpha) * 0.02;
    if (s.alpha < 0.003 && s.target === 0) return;
    const a = s.alpha, f = s.f, N = nodes.length;
    for (const l of links) {
      const A = l.source, B = l.target; let dx = B.x - A.x, dy = B.y - A.y;
      const d = Math.hypot(dx, dy) || 0.01, k = ((d - f.linkDist) / d) * f.linkForce * a * 0.5;
      dx *= k; dy *= k; B.vx -= dx; B.vy -= dy; A.vx += dx; A.vy += dy;
    }
    for (let i = 0; i < N; i++) {
      const A = nodes[i], rA = rad(A, f.nodeSize);
      for (let j = i + 1; j < N; j++) {
        const B = nodes[j]; let dx = B.x - A.x, dy = B.y - A.y, d2 = dx * dx + dy * dy;
        if (d2 > 490000) continue;
        if (d2 < 0.5) { dx = Math.random() - 0.5; dy = Math.random() - 0.5; d2 = dx * dx + dy * dy; }
        let w = Math.min((f.repel * a) / d2, 2);
        const d = Math.sqrt(d2), minD = rA + rad(B, f.nodeSize) + 3;
        if (d < minD) w += ((minD - d) / d) * 0.35;
        A.vx -= dx * w; A.vy -= dy * w; B.vx += dx * w; B.vy += dy * w;
      }
    }
    for (const d of nodes) {
      d.vx -= d.x * f.center * a; d.vy -= d.y * f.center * a;
      if (d.fx != null) { d.x = d.fx; d.y = d.fy; d.vx = 0; d.vy = 0; continue; }
      d.vx *= 0.6; d.vy *= 0.6; d.x += d.vx; d.y += d.vy;
    }
  };
  return s;
}

function Sec({ T, title, open, onToggle, children }) {
  return (
    <div style={{ borderTop: `1px solid ${T.border}` }}>
      <button onClick={onToggle} style={{ width: "100%", display: "flex", justifyContent: "space-between", padding: "10px 14px", fontWeight: 700, fontSize: 15, color: T.panelText }}>{title}<span style={{ transform: open ? "rotate(90deg)" : "none", transition: "transform .15s" }}>›</span></button>
      {open && <div style={{ padding: "0 14px 14px", display: "flex", flexDirection: "column", gap: 10 }}>{children}</div>}
    </div>
  );
}
const Sl = ({ T, label, value, min, max, step, onChange }) => (
  <label style={{ fontSize: 13, color: T.panelText, display: "flex", flexDirection: "column", gap: 2 }}>
    <span className="flex justify-between"><span>{label}</span><span style={{ opacity: 0.6 }}>{Number(value.toFixed(3))}</span></span>
    <input type="range" min={min} max={max} step={step} value={value} onChange={(e) => onChange(+e.target.value)} style={{ accentColor: T.accent }} />
  </label>
);
const Tg = ({ T, label, checked, onChange }) => (
  <button role="switch" aria-checked={checked} onClick={() => onChange(!checked)} className="flex items-center justify-between" style={{ fontSize: 14, color: T.panelText, textAlign: "left" }}>{label}
    <span style={{ width: 34, height: 18, borderRadius: 9, background: checked ? T.accent : T.border, position: "relative", transition: "background .15s", flexShrink: 0 }}><span style={{ position: "absolute", top: 2, left: checked ? 18 : 2, width: 14, height: 14, borderRadius: 7, background: "#fff", transition: "left .15s" }} /></span>
  </button>
);

export default function Grafo() {
  const v = useQuery(qVault), n = useQuery(qNote);
  const [o, setO] = useState({ vault: "", orphans: true, tags: false, ghosts: true });
  const [f, setF] = useState(DEF);
  const [look, setLook] = useState({ theme: "scuro", colorVault: true, arrows: false });
  const [find, setFind] = useState("");
  const [sec, setSec] = useState({ filtri: true, gruppi: false, aspetto: false, forze: false });
  const [panel, setPanel] = useState(true);
  const [hover, setHover] = useState(null);
  const wrap = useRef(null), cv = useRef(null);
  const st = useRef({ t: { k: 1, x: 400, y: 320 }, tt: null, w: 800, h: 640, hover: null, focus: null, nb: new Set(), fade: 0, drag: null, nodes: [], links: [], sim: null, fitted: false });
  const live = useRef({});

  useEffect(() => {
    if (document.getElementById("bi-font")) return;
    const l = document.createElement("link"); l.id = "bi-font"; l.rel = "stylesheet";
    l.href = "https://fonts.googleapis.com/css2?family=Titillium+Web:wght@400;600;700&display=swap";
    document.head.appendChild(l);
  }, []);

  const vaults = v.rows || [];
  const color = (id) => { const i = vaults.findIndex((x) => String(x.id) === String(id)); return PALETTE[(i < 0 ? vaults.length : i) % PALETTE.length]; };
  const vaultName = (id) => vaults.find((x) => String(x.id) === String(id))?.nome || "Senza vault";
  live.current = { look, f, find, color };
  const T = THEMES[look.theme];

  const graph = useMemo(() => buildGraph(n.rows || [], o), [n.rows, o]);

  const fit = () => {
    const s = st.current; if (!s.nodes.length) return;
    const xs = s.nodes.map((d) => d.x), ys = s.nodes.map((d) => d.y);
    const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
    const k = clamp(Math.min(s.w / (x1 - x0 + 140), s.h / (y1 - y0 + 140)), 0.1, 2.5);
    s.tt = { k, x: s.w / 2 - ((x0 + x1) / 2) * k, y: s.h / 2 - ((y0 + y1) / 2) * k };
  };
  const zoom = (z) => { const s = st.current, t = s.tt || s.t, k = clamp(t.k * z, 0.1, 6); s.tt = { k, x: s.w / 2 - ((s.w / 2 - t.x) / t.k) * k, y: s.h / 2 - ((s.h / 2 - t.y) / t.k) * k }; };
  const kick = (a) => { const sm = st.current.sim; if (sm) sm.alpha = Math.max(sm.alpha, a); };

  useEffect(() => {
    const s = st.current;
    const pos = Object.fromEntries(s.nodes.map((d) => [d.id, d]));
    const nodes = graph.nodes.map((d, i) => { const p = pos[d.id]; const ang = i * 2.39996, r = 14 * Math.sqrt(i + 1); return { ...d, x: p ? p.x : r * Math.cos(ang), y: p ? p.y : r * Math.sin(ang) }; });
    const ids = new Set(nodes.map((d) => d.id));
    const links = graph.links.filter((l) => ids.has(l.source) && ids.has(l.target)).map((l) => ({ ...l }));
    s.nodes = nodes; s.links = links; s.hover = null; s.focus = null; s.nb = new Set(); setHover(null);
    s.sim = createSim(nodes, links);
    if (nodes.length && !s.fitted) { s.fitted = true; setTimeout(fit, 1800); }
  }, [graph]);

  useEffect(() => { kick(0.5); }, [f]);

  useEffect(() => {
    const el = wrap.current, c = cv.current;
    const ro = new ResizeObserver(() => {
      const s = st.current, w = el.clientWidth, h = el.clientHeight, dpr = window.devicePixelRatio || 1;
      s.t = { ...s.t, x: s.t.x + (w - s.w) / 2, y: s.t.y + (h - s.h) / 2 }; s.w = w; s.h = h;
      c.width = w * dpr; c.height = h * dpr; c.style.width = w + "px"; c.style.height = h + "px";
    });
    ro.observe(el);
    const onWheel = (e) => {
      e.preventDefault();
      const s = st.current, r = c.getBoundingClientRect(), px = e.clientX - r.left, py = e.clientY - r.top, t = s.t;
      const k = clamp(t.k * Math.exp(-e.deltaY * 0.0015), 0.1, 6);
      s.tt = null; s.t = { k, x: px - ((px - t.x) / t.k) * k, y: py - ((py - t.y) / t.k) * k };
    };
    c.addEventListener("wheel", onWheel, { passive: false });
    let raf;
    const loop = () => {
      raf = requestAnimationFrame(loop);
      const s = st.current, L = live.current, Th = THEMES[L.look.theme], ctx = c.getContext("2d"), dpr = window.devicePixelRatio || 1;
      if (s.sim) { s.sim.f = L.f; s.sim.tick(); }
      if (s.tt) { const t = s.t, g = s.tt; s.t = { k: t.k + (g.k - t.k) * 0.18, x: t.x + (g.x - t.x) * 0.18, y: t.y + (g.y - t.y) * 0.18 }; if (Math.abs(g.k - t.k) < 0.001 && Math.abs(g.x - t.x) < 0.5) { s.t = { ...g }; s.tt = null; } }
      s.fade += ((s.hover ? 1 : 0) - s.fade) * 0.18;
      const { k, x, y } = s.t, fz = s.focus && s.fade > 0.01, fq = norm(L.find);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0); ctx.globalAlpha = 1; ctx.fillStyle = Th.bg; ctx.fillRect(0, 0, s.w, s.h);
      ctx.setTransform(dpr * k, 0, 0, dpr * k, dpr * x, dpr * y);
      ctx.lineWidth = L.f.linkWidth * 0.9;
      for (const l of s.links) {
        const a = l.source, b = l.target, on = fz && (a === s.focus || b === s.focus);
        ctx.globalAlpha = on ? 1 : fz ? 1 - s.fade * 0.8 : 1;
        ctx.strokeStyle = on ? Th.accent : Th.line;
        ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
        if (L.look.arrows) {
          const ang = Math.atan2(b.y - a.y, b.x - a.x), r = rad(b, L.f.nodeSize) + 1.5, ex = b.x - Math.cos(ang) * r, ey = b.y - Math.sin(ang) * r, s2 = 4 + L.f.linkWidth;
          ctx.fillStyle = ctx.strokeStyle; ctx.beginPath(); ctx.moveTo(ex, ey);
          ctx.lineTo(ex - s2 * Math.cos(ang - 0.45), ey - s2 * Math.sin(ang - 0.45)); ctx.lineTo(ex - s2 * Math.cos(ang + 0.45), ey - s2 * Math.sin(ang + 0.45)); ctx.fill();
        }
      }
      for (const d of s.nodes) {
        const r = rad(d, L.f.nodeSize), near = !fz || s.nb.has(d.id);
        ctx.globalAlpha = near ? 1 : 1 - s.fade * 0.8;
        ctx.fillStyle = fz && d === s.focus ? Th.accent : d.kind === "tag" ? Th.tag : d.kind === "ghost" ? Th.ghost : L.look.colorVault ? L.color(d.vault_id) : Th.node;
        ctx.beginPath(); ctx.arc(d.x, d.y, r, 0, 7); ctx.fill();
        if (fq && norm(d.titolo).includes(fq)) { ctx.globalAlpha = 1; ctx.strokeStyle = "#F0A500"; ctx.lineWidth = 2.5 / k; ctx.beginPath(); ctx.arc(d.x, d.y, r + 4 / k, 0, 7); ctx.stroke(); ctx.lineWidth = L.f.linkWidth * 0.9; }
      }
      const base = clamp((k - L.f.textFade) / 0.5, 0, 1), fs = 11 / Math.sqrt(k);
      ctx.font = `600 ${fs}px 'Titillium Web', sans-serif`; ctx.textAlign = "center"; ctx.textBaseline = "top"; ctx.fillStyle = Th.text;
      for (const d of s.nodes) {
        let a = base;
        if (fz) a = s.nb.has(d.id) ? Math.max(a, s.fade) : a * (1 - s.fade * 0.85);
        if (fq && norm(d.titolo).includes(fq)) a = 1;
        if (a < 0.03) continue;
        ctx.globalAlpha = a;
        const t = d.titolo.length > 30 ? d.titolo.slice(0, 29) + "…" : d.titolo;
        ctx.fillText(t, d.x, d.y + rad(d, L.f.nodeSize) + 3);
      }
    };
    loop();
    return () => { cancelAnimationFrame(raf); ro.disconnect(); c.removeEventListener("wheel", onWheel); };
  }, []);

  const toWorld = (e) => { const r = cv.current.getBoundingClientRect(), t = st.current.t; return { x: (e.clientX - r.left - t.x) / t.k, y: (e.clientY - r.top - t.y) / t.k }; };
  const pick = (p) => { const s = st.current; let best = null, bd = Infinity; for (const d of s.nodes) { const dd = Math.hypot(d.x - p.x, d.y - p.y); if (dd < rad(d, f.nodeSize) + 4 / s.t.k && dd < bd) { bd = dd; best = d; } } return best; };
  const setHv = (d) => {
    const s = st.current; if (s.hover === d) return; s.hover = d;
    if (d) { s.focus = d; s.nb = new Set([d.id]); s.links.forEach((l) => { if (l.source === d) s.nb.add(l.target.id); if (l.target === d) s.nb.add(l.source.id); }); }
    setHover(d ? { ...d } : null);
  };
  const onDown = (e) => {
    const s = st.current; cv.current.setPointerCapture(e.pointerId);
    const d = pick(toWorld(e)); s.tt = null;
    s.drag = { node: d, sx: e.clientX, sy: e.clientY, t0: { ...s.t }, moved: false };
    if (d) { d.fx = d.x; d.fy = d.y; if (s.sim) s.sim.target = 0.3; kick(0.3); }
  };
  const onMove = (e) => {
    const s = st.current, dr = s.drag;
    if (!dr) return setHv(pick(toWorld(e)));
    const dx = e.clientX - dr.sx, dy = e.clientY - dr.sy;
    if (Math.abs(dx) + Math.abs(dy) > 3) dr.moved = true;
    if (dr.node) { const p = toWorld(e); dr.node.fx = p.x; dr.node.fy = p.y; }
    else if (dr.moved) s.t = { ...dr.t0, x: dr.t0.x + dx, y: dr.t0.y + dy };
  };
  const onUp = () => {
    const s = st.current, dr = s.drag; s.drag = null; if (!dr?.node) return;
    dr.node.fx = null; dr.node.fy = null; if (s.sim) s.sim.target = 0;
    if (!dr.moved && dr.node.kind === "note") go.nota(dr.node.ref);
  };
  const onLeave = () => { if (!st.current.drag) setHv(null); };

  const loading = v.loading || n.loading, error = v.error || n.error;
  const notes = graph.nodes.filter((d) => d.kind === "note");
  const top = [...notes].sort((a, b) => b.deg - a.deg).filter((d) => d.deg > 0).slice(0, 8);
  const counts = {}; notes.forEach((d) => (counts[d.vault_id] = (counts[d.vault_id] || 0) + 1));
  const nav = [["Home", go.home], ["Tutte le note", go.tutte], ["Grafo dei collegamenti", () => {}, true], ["Importa vault", go.importa]];
  const inp = { height: 34, border: `1px solid ${T.border}`, borderRadius: 4, padding: "0 10px", fontSize: 14, background: T.input, color: T.panelText, fontFamily: FONT, width: "100%" };
  const fbtn = { width: 36, height: 36, borderRadius: 4, background: T.panel, color: T.panelText, border: `1px solid ${T.border}`, fontSize: 17, fontWeight: 700 };
  const setOf = (key) => (val) => setO((p) => ({ ...p, [key]: val }));
  const setFf = (key) => (val) => setF((p) => ({ ...p, [key]: val }));
  const tog = (key) => () => setSec((p) => ({ ...p, [key]: !p[key] }));
  const kindLabel = { note: "Nota", tag: "Tag", ghost: "Nota non ancora creata" };
  const stat = (l, val) => <div style={{ background: "#fff", borderRadius: 4, boxShadow: "0 2px 20px rgba(0,0,0,.08)", padding: "14px 16px", borderLeft: `4px solid ${C.primary}` }}><div style={{ fontSize: 28, fontWeight: 700, color: C.primary, lineHeight: 1 }}>{val}</div><div style={{ fontSize: 13, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".05em", color: C.muted, marginTop: 4 }}>{l}</div></div>;

  return (
    <div style={{ fontFamily: FONT, color: C.text, background: "#fff", fontSize: 18 }}>
      <div style={{ background: C.darker, color: "#fff" }}>
        <div className="max-w-6xl mx-auto px-6 flex items-center justify-between" style={{ height: 48, fontSize: 15 }}>
          <span style={{ fontWeight: 600 }}>Sibilla · Archivio digitale</span>
          <button onClick={go.home} style={{ color: "#fff", fontWeight: 600 }}>← Torna alla home</button>
        </div>
      </div>
      <header style={{ background: C.primary, color: "#fff" }}>
        <div className="max-w-6xl mx-auto px-6 py-6">
          <button onClick={go.home} style={{ color: "#fff", textAlign: "left" }}>
            <div style={{ fontSize: 32, fontWeight: 700, lineHeight: 1.1 }}>Vault Markdown</div>
            <div style={{ fontSize: 16, opacity: 0.9 }}>Leggi e consulta le tue note in stile Obsidian</div>
          </button>
        </div>
        <nav aria-label="Menu principale" style={{ borderTop: "1px solid rgba(255,255,255,.18)" }}>
          <div className="max-w-6xl mx-auto px-6 flex flex-wrap">
            {nav.map(([label, fn, active]) => <button key={label} onClick={fn} style={{ color: "#fff", fontWeight: 600, fontSize: 16, padding: "14px 18px", borderBottom: active ? "3px solid #fff" : "3px solid transparent" }}>{label}</button>)}
          </div>
        </nav>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-8">
        <div style={{ fontSize: 14, color: C.muted }}><button onClick={go.home} style={{ color: C.primary, textDecoration: "underline" }}>Home</button> / Grafo dei collegamenti</div>
        <h1 style={{ fontSize: 40, fontWeight: 700, margin: "6px 0 10px", lineHeight: 1.15 }}>Grafo dei collegamenti</h1>
        <p style={{ fontSize: 20, color: C.muted, maxWidth: 780, margin: "0 0 24px" }}>Ogni nodo è una nota, ogni linea un [[wikilink]]. Passa sopra un nodo per evidenziare i suoi collegamenti, trascinalo per spostarlo, cliccalo per aprire la nota. Avvicinati con lo zoom per leggere i titoli.</p>

        <div ref={wrap} style={{ position: "relative", height: 640, borderRadius: 6, overflow: "hidden", background: T.bg, boxShadow: "0 2px 24px rgba(0,0,0,.14)" }}>
          <canvas ref={cv} style={{ display: "block", cursor: hover ? "pointer" : "grab", touchAction: "none" }} onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerLeave={onLeave} />
          {(loading || error || !graph.nodes.length) && (
            <div style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", color: T.text, textAlign: "center", padding: 24, pointerEvents: "none" }}>
              {error ? <div role="alert">Impossibile caricare i dati: {String(error.message || error)}</div> : loading ? <div>Caricamento del grafo…</div> :
                <div style={{ pointerEvents: "auto" }}>Nessuna nota da mostrare con questi filtri.<br /><button onClick={go.importa} style={{ color: T.accent, fontWeight: 600, textDecoration: "underline" }}>Importa un vault</button></div>}
            </div>
          )}

          {panel ? (
            <div style={{ position: "absolute", top: 12, right: 12, width: 272, maxHeight: "calc(100% - 24px)", overflowY: "auto", background: T.panel, color: T.panelText, border: `1px solid ${T.border}`, borderRadius: 6, boxShadow: "0 6px 24px rgba(0,0,0,.25)", backdropFilter: "blur(6px)" }}>
              <div className="flex items-center justify-between" style={{ padding: "10px 14px" }}>
                <span style={{ fontWeight: 700, fontSize: 15 }}>Impostazioni grafo</span>
                <button onClick={() => setPanel(false)} aria-label="Chiudi impostazioni" style={{ color: T.panelText, fontSize: 18, lineHeight: 1 }}>×</button>
              </div>
              <Sec T={T} title="Filtri" open={sec.filtri} onToggle={tog("filtri")}>
                <input value={find} onChange={(e) => setFind(e.target.value)} placeholder="Cerca nota…" style={inp} aria-label="Cerca nota" />
                <select value={o.vault} onChange={(e) => setOf("vault")(e.target.value)} style={inp} aria-label="Vault">
                  <option value="">Tutti i vault</option>
                  {vaults.map((x) => <option key={x.id} value={String(x.id)}>{x.nome}</option>)}
                </select>
                <Tg T={T} label="Tag" checked={o.tags} onChange={setOf("tags")} />
                <Tg T={T} label="Note non create" checked={o.ghosts} onChange={setOf("ghosts")} />
                <Tg T={T} label="Note isolate" checked={o.orphans} onChange={setOf("orphans")} />
              </Sec>
              <Sec T={T} title="Gruppi" open={sec.gruppi} onToggle={tog("gruppi")}>
                <Tg T={T} label="Colora per vault" checked={look.colorVault} onChange={(val) => setLook((p) => ({ ...p, colorVault: val }))} />
                {vaults.map((x) => (
                  <div key={x.id} className="flex items-center gap-2" style={{ fontSize: 14 }}>
                    <span style={{ width: 12, height: 12, borderRadius: 6, background: look.colorVault ? color(x.id) : T.node, flexShrink: 0 }} />
                    <button onClick={() => go.vault(x.id)} style={{ color: T.panelText, flex: 1, textAlign: "left" }}>{x.nome}</button>
                    <span style={{ opacity: 0.6 }}>{counts[x.id] || 0}</span>
