                {o.tags && <div className="flex items-center gap-2" style={{ fontSize: 14 }}><span style={{ width: 12, height: 12, borderRadius: 6, background: T.tag }} />Tag</div>}
                {o.ghosts && <div className="flex items-center gap-2" style={{ fontSize: 14 }}><span style={{ width: 12, height: 12, borderRadius: 6, background: T.ghost }} />Note non create</div>}
              </Sec>
              <Sec T={T} title="Aspetto" open={sec.aspetto} onToggle={tog("aspetto")}>
                <Tg T={T} label="Tema scuro" checked={look.theme === "scuro"} onChange={(val) => setLook((p) => ({ ...p, theme: val ? "scuro" : "chiaro" }))} />
                <Tg T={T} label="Frecce" checked={look.arrows} onChange={(val) => setLook((p) => ({ ...p, arrows: val }))} />
                <Sl T={T} label="Soglia dissolvenza testo" value={f.textFade} min={0.1} max={2.5} step={0.05} onChange={setFf("textFade")} />
                <Sl T={T} label="Dimensione nodi" value={f.nodeSize} min={0.4} max={2.5} step={0.05} onChange={setFf("nodeSize")} />
                <Sl T={T} label="Spessore collegamenti" value={f.linkWidth} min={0.2} max={4} step={0.1} onChange={setFf("linkWidth")} />
              </Sec>
              <Sec T={T} title="Forze" open={sec.forze} onToggle={tog("forze")}>
                <Sl T={T} label="Forza centrale" value={f.center} min={0} max={0.3} step={0.005} onChange={setFf("center")} />
