                <button onClick={() => setF(DEF)} style={{ ...inp, cursor: "pointer", fontWeight: 600 }}>Ripristina valori</button>
              </Sec>
              <div style={{ borderTop: `1px solid ${T.border}`, padding: 14 }}>
                <button onClick={() => kick(1)} style={{ ...inp, background: T.accent, color: "#fff", border: 0, fontWeight: 700, cursor: "pointer" }}>Riavvia animazione</button>
              </div>
            </div>
          ) : (
            <button onClick={() => setPanel(true)} aria-label="Apri impostazioni" style={{ ...fbtn, position: "absolute", top: 12, right: 12 }}>⚙</button>
          )}

          <div className="flex flex-col gap-2" style={{ position: "absolute", left: 12, top: 12 }}>
            <button style={fbtn} onClick={() => zoom(1.3)} aria-label="Ingrandisci">+</button>
            <button style={fbtn} onClick={() => zoom(1 / 1.3)} aria-label="Riduci">−</button>
