            <button style={{ ...fbtn, fontSize: 15 }} onClick={() => (document.fullscreenElement ? document.exitFullscreen() : wrap.current?.requestFullscreen?.())} aria-label="Schermo intero" title="Schermo intero">⛶</button>
          </div>

          <div style={{ position: "absolute", left: 12, bottom: 12, maxWidth: 360, pointerEvents: "none" }}>
            {hover ? (
              <div style={{ background: T.panel, color: T.panelText, border: `1px solid ${T.border}`, borderRadius: 6, padding: "10px 14px", boxShadow: "0 4px 16px rgba(0,0,0,.25)" }}>
                <div style={{ fontWeight: 700, fontSize: 17 }}>{hover.titolo}</div>
                <div style={{ fontSize: 13, opacity: 0.75 }}>{kindLabel[hover.kind]}{hover.kind === "note" ? ` · ${vaultName(hover.vault_id)}` : ""} · {hover.deg} collegamenti{hover.kind === "note" ? " · clic per aprire" : ""}</div>
