            {stat("Isolate", graph.orphans)}
            {stat("Non create", graph.ghosts)}
          </div>
          <div className="lg:col-span-2">
            <h2 style={{ fontSize: 22, fontWeight: 700, margin: "0 0 10px" }}>Note più collegate</h2>
            {top.length === 0 ? <p style={{ color: C.muted, fontSize: 16 }}>Nessun wikilink trovato. Usa [[Titolo nota]] nel contenuto per collegare le note.</p> : (
