                      <span style={{ width: 10, height: 10, borderRadius: 5, background: color(d.vault_id), flexShrink: 0 }} />
                      <span style={{ flex: 1, color: C.primary, fontWeight: 600, fontSize: 16 }}>{d.titolo}</span>
