            <div style={{ fontSize: 15, opacity: 0.85, marginTop: 6 }}>Interfaccia ispirata a Bootstrap Italia, il design system dei siti della Pubblica Amministrazione.</div>
          </div>
          <div className="flex flex-wrap gap-5" style={{ fontSize: 15, fontWeight: 600 }}>
            {[nav[0], nav[1], nav[3]].map(([label, fn]) => <button key={label} onClick={fn} style={{ color: "#fff", textDecoration: "underline" }}>{label}</button>)}
          </div>
        </div>
      </footer>
    </div>
  );
}

import { useState, useEffect, useMemo } from "react";
import { useQuery, createRecord, navigate } from "sibilla";

const C = { primary: "#0066CC", dark: "#004080", darker: "#003366", text: "#17324D", muted: "#5C6F82", light: "#F2F7FC", border: "#D9E1E8" };
const FONT = "'Titillium Web', Geneva, Tahoma, sans-serif";
const INT = {
  nota: "Lettura di una nota (collezione note, id dalla rotta): contenuto Markdown renderizzato (titoli, elenchi, checklist, grassetto/corsivo, codice, citazioni), [[wikilink]] cliccabili che aprono la nota con quel titolo (/note/:id), tag come chip, metadati (vault, cartella, modificata_il), sezione backlink con le note che la citano, pulsanti per segnare/togliere preferita, modificare titolo/contenuto/tag/cartella ed eliminare la nota. Stile Bootstrap Italia come la home (header blu #0066CC, Titillium Web, footer #004080).",
  tutte: "Elenco di tutte le note di tutti i vault (collezione note), con ricerca per titolo, filtri per vault, cartella e tag, ordinamento per data di modifica; clic su una nota apre /note/:id. Stile Bootstrap Italia come la home (header blu #0066CC, Titillium Web, footer #004080).",
  grafo: "Grafo dei collegamenti tra le note",
  importa: "Importa un vault Obsidian dal computer: selezione di una cartella locale (input file con webkitdirectory) o di più file .md, anteprima dei file trovati, nome e descrizione del vault; crea un record nella collezione vault (percorso = nome cartella) e una nota per ogni file .md (titolo dal nome file, cartella dal percorso relativo, tag dal frontmatter YAML e dai #tag nel testo salvati separati da virgola, contenuto Markdown, modificata_il dalla data del file) con barra di avanzamento; permette anche di creare un vault vuoto. Stile Bootstrap Italia come la home (header blu #0066CC, Titillium Web, footer #004080)."
};
const go = {
  home: () => navigate("/", {}, "Home del Vault Markdown"),
  nota: (id) => navigate("/note/:id", { id }, INT.nota),
  tutte: () => navigate("/note", {}, INT.tutte),
  grafo: () => navigate("/grafo", {}, INT.grafo),
  importa: () => navigate("/importa", {}, INT.importa)
};
const Q = (table, select, where, orderBy) => ({ table, select, join: [], where, groupBy: [], aggregates: [], orderBy, limit: 1000 });
const qVault = Q("vault", ["id", "nome", "descrizione", "percorso"], [{ field: "id", op: "eq", value: "{{id}}" }], []);
const qNote = Q("note", ["id", "titolo", "cartella", "tag", "modificata_il", "preferita"], [{ field: "vault_id", op: "eq", value: "{{id}}" }], [{ field: "modificata_il", dir: "desc" }]);
const tagsOf = (s) => String(s || "").split(",").map((t) => t.trim().replace(/^#/, "")).filter(Boolean);
const fmt = (d) => { if (!d) return "—"; const x = new Date(d); return isNaN(x) ? d : x.toLocaleDateString("it-IT", { day: "2-digit", month: "short", year: "numeric" }); };

function buildTree(notes) {
  const root = { name: "", path: "", children: {}, count: 0 };
  notes.forEach((n) => {
    const parts = String(n.cartella || "").split("/").map((s) => s.trim()).filter(Boolean);
    let cur = root; root.count++;
    parts.forEach((p, i) => {
      const path = parts.slice(0, i + 1).join("/");
      cur.children[p] = cur.children[p] || { name: p, path, children: {}, count: 0 };
      cur = cur.children[p]; cur.count++;
    });
  });
  return root;
}

function Folder({ node, depth, sel, onSel, open, toggle }) {
  const kids = Object.values(node.children).sort((a, b) => a.name.localeCompare(b.name));
  return kids.map((k) => {
    const has = Object.keys(k.children).length > 0, isOpen = open[k.path] !== false, active = sel === k.path;
    return (
      <div key={k.path}>
        <div className="flex items-center" style={{ paddingLeft: depth * 16 }}>
          <button onClick={() => has && toggle(k.path)} aria-label={has ? (isOpen ? "Chiudi" : "Apri") : undefined} style={{ width: 20, color: C.muted, visibility: has ? "visible" : "hidden" }}>{isOpen ? "▾" : "▸"}</button>
          <button onClick={() => onSel(active ? "" : k.path)} className="flex-1 flex items-center justify-between text-left" style={{ padding: "6px 8px", borderRadius: 4, background: active ? C.primary : "transparent", color: active ? "#fff" : C.text, fontWeight: active ? 700 : 600, fontSize: 16 }}>
            <span>📁 {k.name}</span><span style={{ fontSize: 13, opacity: 0.75 }}>{k.count}</span>
          </button>
        </div>
        {has && isOpen && <Folder node={k} depth={depth + 1} sel={sel} onSel={onSel} open={open} toggle={toggle} />}
      </div>
    );
  });
}

export default function VaultView() {
  const m = typeof window !== "undefined" && window.location.pathname.match(/\/vault\/(\d+)/);
  const vars = m ? { id: Number(m[1]) } : undefined;
  const v = useQuery(qVault, vars), n = useQuery(qNote, vars);
  const [q, setQ] = useState("");
  const [folder, setFolder] = useState("");
  const [tag, setTag] = useState("");
  const [open, setOpen] = useState({});
  const [nuova, setNuova] = useState(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (document.getElementById("bi-font")) return;
    const l = document.createElement("link"); l.id = "bi-font"; l.rel = "stylesheet";
    l.href = "https://fonts.googleapis.com/css2?family=Titillium+Web:wght@400;600;700&display=swap";
    document.head.appendChild(l);
  }, []);

  const vault = (v.rows || [])[0];
  const notes = n.rows || [];
  const tree = useMemo(() => buildTree(notes), [notes]);
  const allTags = useMemo(() => { const c = {}; notes.forEach((x) => tagsOf(x.tag).forEach((t) => (c[t] = (c[t] || 0) + 1))); return Object.entries(c).sort((a, b) => b[1] - a[1]); }, [notes]);
  const list = notes.filter((x) => {
    const cf = String(x.cartella || "").split("/").map((s) => s.trim()).filter(Boolean).join("/");
    if (folder && !(cf === folder || cf.startsWith(folder + "/"))) return false;
    if (tag && !tagsOf(x.tag).includes(tag)) return false;
    if (q && !String(x.titolo || "").toLowerCase().includes(q.toLowerCase())) return false;
    return true;
  });
  const nFolders = useMemo(() => new Set(notes.map((x) => String(x.cartella || "").trim()).filter(Boolean)).size, [notes]);
  const lastMod = notes.reduce((a, x) => (x.modificata_il && (!a || x.modificata_il > a) ? x.modificata_il : a), null);

  const crea = async (e) => {
    e.preventDefault(); if (!nuova?.titolo?.trim() || !vault) return;
    setSaving(true);
    try {
      const r = await createRecord("note", { titolo: nuova.titolo.trim(), cartella: nuova.cartella || folder || null, tag: nuova.tag || null, contenuto: "", vault_id: vault.id, preferita: false, modificata_il: new Date().toISOString().slice(0, 10) });
      setNuova(null); n.reload();
      if (r && r.id) go.nota(r.id);
    } finally { setSaving(false); }
  };

  const nav = [["Home", go.home], ["Tutte le note", go.tutte], ["Grafo dei collegamenti", go.grafo], ["Importa vault", go.importa]];
  const card = { background: "#fff", borderRadius: 4, boxShadow: "0 2px 20px rgba(0,0,0,.08)" };
  const inp = { height: 42, border: `1px solid ${C.border}`, borderBottom: `2px solid ${C.muted}`, borderRadius: 0, padding: "0 12px", fontSize: 16, fontFamily: FONT, color: C.text, background: "#fff", width: "100%" };
  const stat = (l, val) => <div style={{ ...card, padding: "14px 16px", borderLeft: `4px solid ${C.primary}` }}><div style={{ fontSize: 26, fontWeight: 700, color: C.primary, lineHeight: 1 }}>{val}</div><div style={{ fontSize: 13, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".05em", color: C.muted, marginTop: 4 }}>{l}</div></div>;
  const loading = v.loading || n.loading, error = v.error || n.error;

  return (
    <div style={{ fontFamily: FONT, color: C.text, background: "#fff", fontSize: 18 }}>
      <div style={{ background: C.darker, color: "#fff" }}>
        <div className="max-w-6xl mx-auto px-6 flex items-center justify-between" style={{ height: 48, fontSize: 15 }}>
          <span style={{ fontWeight: 600 }}>Sibilla · Archivio digitale</span>
