                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {list.map((x) => (
                    <button key={x.id} onClick={() => go.nota(x.id)} className="text-left hover:shadow-lg transition-shadow" style={{ ...card, padding: "16px 18px", borderTop: `4px solid ${C.primary}`, display: "flex", flexDirection: "column", gap: 6 }}>
                      <div style={{ fontSize: 13, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".05em", color: C.muted }}>{x.cartella ? `📁 ${x.cartella}` : "Radice"}</div>
