                      <div style={{ fontSize: 14, color: C.muted, marginTop: "auto" }}>Modificata il {fmt(x.modificata_il)} · <span style={{ color: C.primary, fontWeight: 600 }}>Leggi →</span></div>
                    </button>
                  ))}
                </div>
              )}
            </section>
          </div>
        </>)}
      </main>

      <footer style={{ background: C.dark, color: "#fff", marginTop: 32 }}>
        <div className="max-w-6xl mx-auto px-6 py-8 flex flex-wrap items-end justify-between gap-6">
