          <div className="flex flex-wrap gap-5" style={{ fontSize: 15, fontWeight: 600 }}>
            {nav.map(([label, fn]) => <button key={label} onClick={fn} style={{ color: "#fff", textDecoration: "underline" }}>{label}</button>)}
          </div>
        </div>
      </footer>
    </div>
  );
}

