  tutte: () => navigate("/note", {}, INT.tutte),
  nuova: () => navigate("/nuova-nota", {}, INT.nuova),
  importa: () => navigate("/importa", {}, INT.importa),
  grafo: () => navigate("/grafo", {}, INT.grafo),
  cerca: (testo) => navigate("/cerca/:testo", { testo }, INT.cerca)
};

const Q = (table, select, orderBy, limit = null) => ({ table, select, join: [], where: [], groupBy: [], aggregates: [], orderBy, limit });
const qVault = Q("vault", ["id", "nome", "descrizione", "percorso"], [{ field: "nome", dir: "asc" }]);
const qNote = Q("note", ["id", "titolo", "vault_id", "cartella", "tag", "preferita", "modificata_il"], [{ field: "modificata_il", dir: "desc" }], 1000);

const PATHS = {
  book: <><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5z" /><path d="M4 19.5A2.5 2.5 0 0 0 6.5 22H20v-5" /><path d="M8 7h8M8 11h6" /></>,
  folder: <path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />,
  file: <><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z" /><path d="M14 3v5h5M9 13h6M9 17h4" /></>,
  search: <><circle cx="11" cy="11" r="7" /><path d="m20 20-3.5-3.5" /></>,
  star: <path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1 6.2L12 17.3 6.5 20.2l1-6.2L3 9.6l6.2-.9z" />,
  arrow: <path d="M5 12h14M13 6l6 6-6 6" />,
  plus: <path d="M12 5v14M5 12h14" />,
  upload: <><path d="M12 16V4M7 9l5-5 5 5" /><path d="M4 20h16" /></>,
  graph: <><circle cx="6" cy="6" r="2.5" /><circle cx="18" cy="8" r="2.5" /><circle cx="10" cy="18" r="2.5" /><path d="M8.4 6.3l7.2 1.3M6.8 8.4l2.4 7.2M16.6 10.1l-5 6" /></>
};
function Icon({ name, size = 20, fill = "none" }) {
  return <svg width={size} height={size} viewBox="0 0 24 24" fill={fill} stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{PATHS[name]}</svg>;
}

const tagsOf = (t) => (t || "").split(",").map((s) => s.trim().replace(/^#/, "")).filter(Boolean);
const fmt = (d) => (d ? new Date(String(d).slice(0, 10) + "T00:00:00").toLocaleDateString("it-IT", { day: "2-digit", month: "short", year: "numeric" }) : "—");
const card = { background: "#fff", borderRadius: 4, boxShadow: "0 2px 20px rgba(0,0,0,.08)" };
const btn = (outline) => ({ background: outline ? "#fff" : C.primary, color: outline ? C.primary : "#fff", border: `2px solid ${C.primary}`, borderRadius: 4, padding: "10px 22px", fontWeight: 600, fontSize: 16, display: "inline-flex", alignItems: "center", gap: 8, cursor: "pointer" });

function MoreLink({ onClick, children }) {
  return <button onClick={onClick} style={{ color: C.primary, fontWeight: 600, background: "none", border: 0, padding: 0, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 6, fontSize: 15 }}>{children}<Icon name="arrow" size={16} /></button>;
}
function H2({ children, action }) {
  return <div className="flex items-end justify-between gap-4 mb-5"><h2 style={{ fontSize: 28, fontWeight: 700, color: C.text, margin: 0 }}>{children}</h2>{action}</div>;
}

export default function VaultHome() {
  const v = useQuery(qVault);
  const n = useQuery(qNote);
  const [q, setQ] = useState("");
  const [focus, setFocus] = useState(false);

  useEffect(() => {
    if (document.getElementById("bi-font")) return;
    const l = document.createElement("link");
    l.id = "bi-font"; l.rel = "stylesheet";
    l.href = "https://fonts.googleapis.com/css2?family=Titillium+Web:wght@400;600;700&display=swap";
    document.head.appendChild(l);
  }, []);

  const vaults = v.rows || [];
  const notes = n.rows || [];
  const { perVault, tags, fav } = useMemo(() => {
    const perVault = {}, tc = {};
    (n.rows || []).forEach((x) => {
      const k = String(x.vault_id);
      perVault[k] = (perVault[k] || 0) + 1;
      tagsOf(x.tag).forEach((t) => (tc[t] = (tc[t] || 0) + 1));
    });
    return { perVault, tags: Object.entries(tc).sort((a, b) => b[1] - a[1]), fav: (n.rows || []).filter((x) => !!x.preferita) };
  }, [n.rows]);
  const vaultName = (id) => vaults.find((x) => String(x.id) === String(id))?.nome || "Senza vault";
  const loading = v.loading || n.loading;
  const error = v.error || n.error;
  const search = (e) => { e.preventDefault(); const t = q.trim(); if (t) go.cerca(t); };

  const nav = [["Home", go.home, true], ["Tutte le note", go.tutte], ["Grafo dei collegamenti", go.grafo], ["Importa vault", go.importa]];
  const kpis = [["Vault", vaults.length], ["Note", notes.length], ["Tag", tags.length], ["Preferite", fav.length]];

  return (
    <div style={{ fontFamily: FONT, color: C.text, background: "#fff", fontSize: 18 }}>
      <div style={{ background: C.darker, color: "#fff" }}>
        <div className="max-w-6xl mx-auto px-6 flex items-center justify-between" style={{ height: 48, fontSize: 15 }}>
          <span style={{ fontWeight: 600 }}>Sibilla · Archivio digitale</span>
          <button onClick={go.importa} className="flex items-center gap-2" style={{ color: "#fff", fontWeight: 600 }}><Icon name="upload" size={16} />Importa vault</button>
        </div>
      </div>

      <header style={{ background: C.primary, color: "#fff" }}>
        <div className="max-w-6xl mx-auto px-6 py-6 flex flex-wrap items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <div style={{ width: 64, height: 64, borderRadius: 4, background: "#fff", color: C.primary, display: "grid", placeItems: "center" }}><Icon name="book" size={36} /></div>
            <div>
              <div style={{ fontSize: 32, fontWeight: 700, lineHeight: 1.1 }}>Vault Markdown</div>
              <div style={{ fontSize: 16, opacity: 0.9 }}>Leggi e consulta le tue note in stile Obsidian</div>
            </div>
          </div>
          <form onSubmit={search} role="search" className="flex items-center gap-3">
            <label htmlFor="cerca-note" className="hidden md:block" style={{ fontWeight: 600, fontSize: 16, color: "#fff" }}>Cerca</label>
            <div style={{ position: "relative", display: "flex", alignItems: "center" }}>
              <input id="cerca-note" type="search" value={q} onChange={(e) => setQ(e.target.value)} onFocus={() => setFocus(true)} onBlur={() => setFocus(false)} placeholder="Cerca nelle note…" className="placeholder:text-[#5C6F82]" style={{ width: 300, height: 48, borderRadius: 24, border: "2px solid #fff", background: "#FFFFFF", backgroundColor: "#FFFFFF", padding: "0 56px 0 20px", color: C.text, fontSize: 16, fontFamily: FONT, outline: "none", boxShadow: focus ? "0 0 0 3px #FF9900" : "0 1px 4px rgba(0,0,0,.15)", WebkitAppearance: "none", appearance: "none" }} />
              <button type="submit" aria-label="Cerca" style={{ position: "absolute", right: 4, top: 4, width: 40, height: 40, borderRadius: 20, background: C.primary, color: "#fff", display: "grid", placeItems: "center", border: 0, cursor: "pointer" }}><Icon name="search" size={18} /></button>
            </div>
          </form>
        </div>
        <nav aria-label="Menu principale" style={{ borderTop: "1px solid rgba(255,255,255,.18)" }}>
          <div className="max-w-6xl mx-auto px-6 flex flex-wrap">
            {nav.map(([label, fn, active]) => (
              <button key={label} onClick={fn} style={{ color: "#fff", fontWeight: 600, fontSize: 16, padding: "14px 18px", borderBottom: active ? "3px solid #fff" : "3px solid transparent" }}>{label}</button>
            ))}
          </div>
        </nav>
      </header>

      <main>
        <section className="max-w-6xl mx-auto px-6 pt-8 pb-8">
          <div style={{ fontSize: 14, color: C.muted }}>Home</div>
          <h1 style={{ fontSize: 40, fontWeight: 700, margin: "6px 0 10px", lineHeight: 1.15 }}>Il tuo archivio di note</h1>
          <p style={{ fontSize: 20, color: C.muted, maxWidth: 740, margin: 0 }}>Importa i vault di Obsidian (cartelle di file .md), naviga tra cartelle e collegamenti [[wikilink]] e ritrova ogni appunto in un attimo.</p>
          <div className="flex flex-wrap gap-3 mt-6">
            <button onClick={go.nuova} style={btn(false)}><Icon name="plus" size={18} />Nuova nota</button>
            <button onClick={go.importa} style={btn(true)}><Icon name="upload" size={18} />Importa vault</button>
            <button onClick={go.grafo} style={btn(true)}><Icon name="graph" size={18} />Grafo</button>
          </div>
        </section>

        {error ? (
          <div className="max-w-6xl mx-auto px-6 pb-10"><div role="alert" style={{ borderLeft: "4px solid #D9364F", background: "#FDF2F4", padding: 16, borderRadius: 4 }}>Impossibile caricare i dati: {String(error.message || error)}</div></div>
        ) : loading ? (
          <div className="max-w-6xl mx-auto px-6 pb-10" style={{ color: C.muted }}>Caricamento in corso…</div>
        ) : (
          <>
            <section style={{ background: C.light }}>
              <div className="max-w-6xl mx-auto px-6 py-10">
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-10">
                  {kpis.map(([l, val]) => (
                    <div key={l} style={{ ...card, padding: 20, borderLeft: `4px solid ${C.primary}` }}>
                      <div style={{ fontSize: 36, fontWeight: 700, color: C.primary, lineHeight: 1 }}>{val}</div>
                      <div style={{ fontSize: 14, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".05em", color: C.muted, marginTop: 6 }}>{l}</div>
                    </div>
                  ))}
                </div>
                <H2>I tuoi vault</H2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {vaults.map((x) => (
                    <article key={x.id} style={{ ...card, padding: 24, display: "flex", flexDirection: "column" }}>
                      <div className="flex items-center gap-2" style={{ fontSize: 14, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".05em", color: C.muted }}><Icon name="folder" size={18} />Vault</div>
                      <h3 style={{ fontSize: 24, fontWeight: 700, margin: "10px 0 6px" }}><button onClick={() => go.vault(x.id)} style={{ color: C.primary, textAlign: "left" }}>{x.nome}</button></h3>
                      <p style={{ color: C.muted, fontSize: 16, margin: "0 0 12px", flex: 1 }}>{x.descrizione || "Nessuna descrizione"}</p>
                      {x.percorso && <code style={{ fontSize: 13, background: C.light, padding: "3px 8px", borderRadius: 4, alignSelf: "flex-start", color: C.text }}>{x.percorso}</code>}
                      <div className="flex items-center justify-between mt-5 pt-4" style={{ borderTop: `1px solid ${C.border}` }}>
                        <span style={{ fontWeight: 600, fontSize: 16 }}>{perVault[String(x.id)] || 0} note</span>
                        <MoreLink onClick={() => go.vault(x.id)}>Esplora</MoreLink>
                      </div>
                    </article>
                  ))}
                  <button onClick={go.importa} style={{ border: `2px dashed ${C.primary}`, borderRadius: 4, padding: 24, minHeight: 200, color: C.primary, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 10, background: "rgba(255,255,255,.6)" }}>
                    <Icon name="upload" size={32} />
                    <span style={{ fontWeight: 700, fontSize: 20 }}>Aggiungi un vault</span>
                    <span style={{ fontSize: 15, color: C.muted }}>Importa una cartella di file .md</span>
                  </button>
                </div>
              </div>
            </section>

            <section className="max-w-6xl mx-auto px-6 py-10 grid grid-cols-1 lg:grid-cols-3 gap-10">
              <div className="lg:col-span-2">
                <H2 action={<MoreLink onClick={go.tutte}>Tutte le note</MoreLink>}>Modificate di recente</H2>
                {notes.length === 0 ? (
                  <p style={{ color: C.muted }}>Nessuna nota ancora. <button onClick={go.nuova} style={{ color: C.primary, fontWeight: 600, textDecoration: "underline" }}>Scrivi la prima</button></p>
                ) : (
                  <ul style={{ borderTop: `1px solid ${C.border}`, margin: 0, padding: 0, listStyle: "none" }}>
                    {notes.slice(0, 7).map((x) => (
                      <li key={x.id}>
                        <button onClick={() => go.nota(x.id)} className="w-full text-left flex items-center gap-4 hover:bg-[#F2F7FC]" style={{ padding: "14px 8px", borderBottom: `1px solid ${C.border}` }}>
                          <span style={{ color: C.primary }}><Icon name="file" size={22} /></span>
                          <span className="flex-1 min-w-0">
                            <span style={{ display: "block", fontWeight: 600, fontSize: 18, color: C.primary }}>{x.titolo}</span>
                            <span style={{ fontSize: 14, color: C.muted }}>{vaultName(x.vault_id)}{x.cartella ? " · " + x.cartella : ""}</span>
                          </span>
                          <span style={{ fontSize: 14, color: C.muted, whiteSpace: "nowrap" }}>{fmt(x.modificata_il)}</span>
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
              <aside>
                <h2 style={{ fontSize: 22, fontWeight: 700, margin: "0 0 12px" }}>Preferite</h2>
                {fav.length === 0 ? <p style={{ color: C.muted, fontSize: 16 }}>Nessuna nota preferita.</p> : (
                  <ul style={{ margin: "0 0 32px", padding: 0, listStyle: "none" }}>
                    {fav.slice(0, 6).map((x) => (
                      <li key={x.id} style={{ marginBottom: 10 }}>
                        <button onClick={() => go.nota(x.id)} className="flex items-start gap-2 text-left" style={{ color: C.primary, fontWeight: 600, fontSize: 17 }}>
                          <span style={{ color: "#CC7A00", marginTop: 3 }}><Icon name="star" size={16} fill="currentColor" /></span>{x.titolo}
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
                <h2 style={{ fontSize: 22, fontWeight: 700, margin: "0 0 12px" }}>Tag più usati</h2>
                {tags.length === 0 ? <p style={{ color: C.muted, fontSize: 16 }}>Nessun tag.</p> : (
                  <div className="flex flex-wrap gap-2">
                    {tags.slice(0, 14).map(([t, c]) => (
                      <button key={t} onClick={() => go.cerca(t)} style={{ border: `1px solid ${C.primary}`, color: C.primary, borderRadius: 16, padding: "3px 12px", fontSize: 14, fontWeight: 600, background: "#fff" }}>#{t} <span style={{ color: C.muted, fontWeight: 400 }}>{c}</span></button>
                    ))}
                  </div>
                )}
              </aside>
            </section>
          </>
        )}
      </main>

      <footer style={{ background: C.dark, color: "#fff" }}>
        <div className="max-w-6xl mx-auto px-6 py-8 flex flex-wrap items-end justify-between gap-6">
          <div>
            <div className="flex items-center gap-3" style={{ fontSize: 24, fontWeight: 700 }}><Icon name="book" size={28} />Vault Markdown</div>
            <div style={{ fontSize: 15, opacity: 0.85, marginTop: 6 }}>Interfaccia ispirata a Bootstrap Italia, il design system dei siti della Pubblica Amministrazione.</div>
          </div>
          <div className="flex flex-wrap gap-5" style={{ fontSize: 15, fontWeight: 600 }}>
            {nav.slice(1).map(([label, fn]) => <button key={label} onClick={fn} style={{ color: "#fff", textDecoration: "underline" }}>{label}</button>)}
          </div>
        </div>
      </footer>
    </div>
  );
}
